let titles = data

let container = document.querySelector(".container");
container.innerHTML = '<div class="navbar"></div>' + container.innerHTML
let navbar = document.querySelector(".navbar");
navbar.innerHTML += '<input placeholder="نام فارسی یا انگلیسی فیلم" type="text" class="searchbar">'
navbar.innerHTML += '<button class="navBtn" onclick="goHome()">' + "خانه" + "</button>"
navbar.innerHTML += '<a target="_blank" href="https://daramet.com/donyayeserial"><button class="navBtn" onclick="goHome()">' + "حمایت از ما" + "</button></a>"
navbar.innerHTML += '<a target="_blank" href="https://dls2.film2cinemaha.top/DonyayeSerial/donyaye_serial_all_archive.html"><button class="navBtn" onclick="goHome()">' + "ورژن قدیمی" + "</button></a>"
navbar.innerHTML += '<a target="_blank" href="https://serialblog1.top/"><button class="navBtn" style="background-color:red;" onclick="goHome()">' + "آدرس جدید سایت" + "</button></a>"
navbar.innerHTML += '<a target="_blank" href="https://serialblog.rzb.ir/"><button class="navBtn" style="background-color:red;" onclick="goHome()">' + "وبلاگ" + "</button></a>"
container.innerHTML = '<div class="notif"></div>' + container.innerHTML

let searchbar = document.querySelector(".searchbar")
searchbar.addEventListener("keyup", doSearch)

function goHome() {
    titles = data
    make_article_page(1)
    searchbar.value = ""
}

function doSearch () {
    let searchbar = document.querySelector(".searchbar")
    let s = searchbar.value;
    s = s.toLowerCase()
    console.log(s)
    let title;
    let results = [];
    for (title in data) {
        title = data[title];
        if ((titleTypeMap(title[1]) + " " + title[2].toLowerCase() + " " + title[4]).includes(s)) {
            results.push(title)
        } else if ((titleTypeMap(title[1]) + " " + title[3] + " " + title[4]).includes(s)) {
            results.push(title)
        }
    }
    titles = results
    make_article_page(1);
}

let row = document.querySelector(".row");
function titleTypeMap (titleType) {
    if (titleType.toLowerCase().includes("movie")) {
        return "فیلم"
    } else {
        return "سریال"
    }
}

function make_post_page(title_code, current_page) {
    row.innerHTML = '<div class="post"></div>';
    let post = document.querySelector(".post")
    let versionMap = {1:"زیرنویس فارسی", 2:"دوبله فارسی", 3:"بدون زیرنویس"}
    let title_data;
    let title;
    for (title in data) {
        title = data[title];
        if (title[0] == title_code) {
            title_data = title;
            break;
        }
    }
    let all_html = "";
    all_html += "<h2>" + titleTypeMap(title_data[1]) + " " + title_data[3] + " " + title_data[2] + " " + title_data[4] + "</h2>"
    all_html += '<p class="imdb">' + "<b>" + "IMDb: " + "</b>" + title_data[6].toLocaleString() + " - " + title_data[5] + "/10" + "</p>"
    let links = title_data[7]
    if (titleTypeMap(title_data[1])  == "فیلم") {
        for (v in links) {
            all_html += "<h3>نسخه " + versionMap[v] + "</h3>"
            for (l in links[v]) {
                let link = links[v][l]
                all_html += '<p class="link"><a href="'+link["file"]+'">'+link["quality"].replace(".", " ") + '</a>' +" / "+link["size"]+ '</p>'
            }
            all_html += "<hr>"
        }
    } else {
        for (v in links) {
            all_html += "<h3>نسخه " + versionMap[v] + "</h3>"
            for (s in links[v]){
                    all_html += "<h4>فصل "+s+"</h4>"
                    for (l in links[v][s]) {
                        let link = links[v][s][l]
                        all_html += '<p class="link"><a href="'+link["folder"]+'">'+link["quality"].replace(".", " ") + '</a>' + " / " + link["number_of_episodes"] +" Ep / "+(Math.floor(link["avg_episode_size"] / 1048576)).toLocaleString() + ' MB</p>'
                    }
            }
            all_html += "<hr>"
        }
    }
    all_html += "<h3>فیلم و سریالهای مرتبط: </h3>"
    console.log( title_data[8])
    for (rel in title_data[8]) {
        let title2;
        let title2_data
        for (title2 in data) {
            title2 = data[title2];
            if (title2[0] == title_data[8][rel]) {
                title2_data = title2;
                break;
        }
        }
        if (title2_data){
        all_html += '<p onclick="make_post_page(`'+title2_data[0]+'`,'+current_page +')" class="link"><a href="#'+title2_data[0]+'">' + titleTypeMap(title2_data[1]) + " " + title2_data[3] + " " + title2_data[2] + " " + title2_data[4] + '</a></p>'
        }

    }
    post.innerHTML = all_html;
    post.innerHTML += '<button onclick="make_article_page('+current_page+')">برگشت به صفحه قبل >></button>'
}

function make_article_page(current_page){
    row.innerHTML = '<div class="articles"> </div>';
    let articles = document.querySelector(".articles");

    let total_pages;
    if (titles.length % 9 == 0){
        total_pages = Math.floor(titles.length / 9);
    } else {
        total_pages = Math.floor(titles.length / 9) + 1;
    }
    
    console.log(total_pages);
    for (let i= (current_page - 1) * 9; i < current_page *9; i++) {
        if (titles.length <= i){
            break;
        };
        let title = titles[i]
        articles.innerHTML += '<div class="article"></div>';
        let article = document.querySelectorAll(".article")[i % 9]
        article.innerHTML += "<p>" + (i+1) + ". " + titleTypeMap(title[1]) + " " + title[3] + " " + title[2] + " " + title[4] + "</p>"
        article.innerHTML += '<p class="imdb">' + "<b>" + "IMDb: " + "</b>" + title[6].toLocaleString() + " - " + title[5] + "/10" + "</p>"
        article.innerHTML += '<button id="' + title[0] +'" onclick="make_post_page(this.id, '+current_page+')">مشاهده لینک ها</button>'

    }

    row.innerHTML += '<div class="pagination"></div>';

    let pagination = document.querySelector(".pagination");
    
    pagination.innerHTML += '<button id="first" class="unactive"><<</button>';
    pagination.innerHTML += '<button id="before" class="unactive"><</button>';
    pagination.innerHTML += '<button id="current" style="width:50px">'+current_page+'</button>';
    pagination.innerHTML += '<button id="next" class="unactive">></button>';
    pagination.innerHTML += '<button id="last" class="unactive">>></button>';
    

    function nextCall () {
        make_article_page(current_page + 1)
    }

    function lastCall () {
        make_article_page(total_pages)
    }
    if (current_page > 1 ){
        let first = document.getElementById("first");
        first.classList.remove("unactive")
        first.addEventListener("click", function(){make_article_page(1)});
        let before = document.getElementById("before");
        before.classList.remove("unactive")
        before.addEventListener("click", function(){make_article_page(current_page-1)});
    }
    let current = document.querySelector("#current");
    current.addEventListener("click", function(){make_article_page(current_page)}); 
    if (current_page < total_pages){
        let next = document.querySelector("#next");
        next.classList.remove("unactive")
        next.addEventListener("click", nextCall);
        let last = document.querySelector("#last");
        last.classList.remove("unactive")
        last.addEventListener("click", lastCall);
    }
    
};
// debugger;
make_article_page(1);